 },
 {
  "lang": "es",
  "en": "LumiPlus FlexiMini is the compact member of the LumiPlus Flexi family, in line with today's design trends for private pools. Mix and match the light colour, a visible front in white, beige, grey, anthracite or stainless steel, and the installation method: mini niche, large or small inlet, or installation pipe. Made in Europe.",
  "text": "LumiPlus FlexiMini es el miembro compacto de la familia LumiPlus Flexi, en línea con las tendencias de diseño actuales para piscinas privadas. Combina a tu gusto el color de la luz, un embellecedor visible en blanco, beige, gris, antracita o acero inoxidable y el método de instalación: mini nicho, boquilla grande o pequeña, o tubo de instalación. Fabricado en Europa."
 },
 {
  "lang": "sv",
  "en": "LumiPlus FlexiMini is the compact member of the LumiPlus Flexi family, in line with today's design trends for private pools. Mix and match the light colour, a visible front in white, beige, grey, anthracite or stainless steel, and the installation method: mini niche, large or small inlet, or installation pipe. Made in Europe.",
  "text": "LumiPlus FlexiMini är den kompakta medlemmen i LumiPlus Flexi-familjen, i linje med dagens designtrender för privata pooler. Kombinera fritt ljusfärg, en synlig front i vitt, beige, grått, antracit eller rostfritt stål och installationssätt: mininisch, stort eller litet inlopp, eller installationsrör. Tillverkad i Europa."
 },
 {
  "lang": "es",
  "en": "V1: 450 lm white / 300 lm RGB; V2: 900 lm white / 600 lm RGB",
  "text": "V1: 450 lm blanco / 300 lm RGB; V2: 900 lm blanco / 600 lm RGB"
 },
