 {
  "lang": "es",
  "en": "Polished AISI-316 stainless-steel handrails for steps and pool entries.",
  "text": "Pasamanos de acero inoxidable AISI-316 pulido para escaleras y entradas a la piscina."
 },
 {
  "lang": "sv",
  "en": "Polished AISI-316 stainless-steel handrails for steps and pool entries.",
  "text": "Ledstänger i polerat rostfritt stål AISI-316 för trappor och nedgångar i poolen."
 },
 {
  "lang": "es",
  "en": "Polished stainless-steel handrails in AISI-316, 43 mm tube, for safe and elegant pool entries. Available as a pair (470 × 800 mm, round or rectangular fixing plates) or as a single long rail (800 × 1,250 mm), supplied with fixing plates, gaskets, screws and plugs.",
  "text": "Pasamanos de acero inoxidable pulido AISI-316, con tubo de 43 mm, para entradas a la piscina seguras y elegantes. Disponibles por parejas (470 × 800 mm, con placas de fijación redondas o rectangulares) o como pasamanos largo individual (800 × 1250 mm), y se suministran con placas de fijación, juntas, tornillos y tacos."
 },
 {
  "lang": "sv",
  "en": "Polished stainless-steel handrails in AISI-316, 43 mm tube, for safe and elegant pool entries. Available as a pair (470 × 800 mm, round or rectangular fixing plates) or as a single long rail (800 × 1,250 mm), supplied with fixing plates, gaskets, screws and plugs.",
  "text": "Ledstänger i polerat rostfritt stål AISI-316, 43 mm rör, för säkra och eleganta nedgångar i poolen. Finns som par (470 × 800 mm, med runda eller rektangulära fästplattor) eller som en enkel lång ledstång (800 × 1 250 mm) och levereras med fästplattor, packningar, skruvar och pluggar."
 },
