]$data$::jsonb) as x(lang text, en text, text text);

create index on tr (lang, en);

update public.products p set
  tagline_es = coalesce(nullif(p.tagline_es, ''), (select t.text from tr t where t.lang = 'es' and t.en = p.tagline)),
  description_es = coalesce(nullif(p.description_es, ''), (select t.text from tr t where t.lang = 'es' and t.en = p.description)),
  tagline_sv = coalesce(nullif(p.tagline_sv, ''), (select t.text from tr t where t.lang = 'sv' and t.en = p.tagline)),
  description_sv = coalesce(nullif(p.description_sv, ''), (select t.text from tr t where t.lang = 'sv' and t.en = p.description));

update public.products p set specs = coalesce((
  select jsonb_agg(e || jsonb_strip_nulls(jsonb_build_object(
    'group_es', coalesce(nullif(e->>'group_es', ''), (select t.text from tr t where t.lang = 'es' and t.en = e->>'group')),
    'label_es', coalesce(nullif(e->>'label_es', ''), (select t.text from tr t where t.lang = 'es' and t.en = e->>'label')),
    'value_es', coalesce(nullif(e->>'value_es', ''), (select t.text from tr t where t.lang = 'es' and t.en = e->>'value')),
    'group_sv', coalesce(nullif(e->>'group_sv', ''), (select t.text from tr t where t.lang = 'sv' and t.en = e->>'group')),
    'label_sv', coalesce(nullif(e->>'label_sv', ''), (select t.text from tr t where t.lang = 'sv' and t.en = e->>'label')),
    'value_sv', coalesce(nullif(e->>'value_sv', ''), (select t.text from tr t where t.lang = 'sv' and t.en = e->>'value'))
  )) order by i)
  from jsonb_array_elements(p.specs) with ordinality as s(e, i)
), '[]'::jsonb)
where jsonb_array_length(p.specs) > 0;

drop table tr;

select
  count(*) filter (where description_es is not null) as translated_es,
  count(*) filter (where description_sv is not null) as translated_sv,
  count(*) as products
from public.products;
